SELECT w.date, w.daily_waste, s.daily_sales, (w.daily_waste::numeric/s.daily_sales::numeric)*100 as waste_ratio_pct 
FROM (
    SELECT date, SUM(units_wasted) as daily_waste, SUM(waste_cost) as daily_cost 
    FROM cases.waste_table WHERE store_id = 'CAF-STK-02' AND date LIKE '2026-08%' GROUP BY date
) w 
JOIN (
    SELECT date, SUM(units_sold) as daily_sales, SUM(revenue) as daily_revenue 
    FROM cases.sales_table WHERE store_id = 'CAF-STK-02' AND date LIKE '2026-08%' GROUP BY date
) s ON w.date = s.date 
ORDER BY waste_ratio_pct DESC;
